node --input-type=module <<'EOF'
// Inline port of the validator's core checks for our three colors
// Blue: #1a56c4, Red: #c0392b, Gray: #898781

function hexToRgb(hex) {
  const r = parseInt(hex.slice(1,3),16)/255;
  const g = parseInt(hex.slice(3,5),16)/255;
  const b = parseInt(hex.slice(5,7),16)/255;
  return [r,g,b];
}

function toLinear(c) {
  return c <= 0.04045 ? c/12.92 : Math.pow((c+0.055)/1.055, 2.4);
}

function relLum([r,g,b]) {
  const [rl,gl,bl] = [r,g,b].map(toLinear);
  return 0.2126*rl + 0.7152*gl + 0.0722*bl;
}

function contrast(hexA, hexB) {
  const la = relLum(hexToRgb(hexA));
  const lb = relLum(hexToRgb(hexB));
  const [hi,lo] = [la,lb].sort((a,b)=>b-a);
  return (hi+0.05)/(lo+0.05);
}

// Surface
const surface = "#fcfcfb";
const colors = {
  Democratic: "#1a56c4",
  Republican: "#c0392b",
  Neutral: "#898781"
};

console.log("Contrast vs light surface (#fcfcfb):");
for (const [name, hex] of Object.entries(colors)) {
  const c = contrast(hex, surface);
  console.log(`  ${name} (${hex}): ${c.toFixed(2)}:1 ${c >= 3 ? "PASS" : "FAIL"}`);
}

// OKLab conversion for deltaE
function linearToOkLab(r, g, b) {
  // sRGB linear to OKLab
  const l_ = 0.4122214708*r + 0.5363325363*g + 0.0514459929*b;
  const m_ = 0.2119034982*r + 0.6806995451*g + 0.1073969566*b;
  const s_ = 0.0883024619*r + 0.2817188376*g + 0.6299787005*b;
  const l = Math.cbrt(l_);
  const m = Math.cbrt(m_);
  const s = Math.cbrt(s_);
  return [
    0.2104542553*l + 0.7936177850*m - 0.0040720468*s,
    1.9779984951*l - 2.4285922050*m + 0.4505937099*s,
    0.0259040371*l + 0.4072456201*m - 0.4631496132*s
  ];
}

function hexToOkLab(hex) {
  const rgb = hexToRgb(hex).map(toLinear);
  return linearToOkLab(...rgb);
}

function deltaE(hexA, hexB) {
  const [L1,a1,b1] = hexToOkLab(hexA);
  const [L2,a2,b2] = hexToOkLab(hexB);
  return Math.sqrt((L1-L2)**2 + (a1-a2)**2 + (b1-b2)**2) * 100;
}

console.log("\nNormal-vision ΔE (OKLab×100) between pairs:");
const entries = Object.entries(colors);
for (let i=0;i<entries.length;i++) {
  for (let j=i+1;j<entries.length;j++) {
    const dE = deltaE(entries[i][1], entries[j][1]);
    console.log(`  ${entries[i][0]} vs ${entries[j][0]}: ${dE.toFixed(1)} ${dE>=15?"PASS":"WARN"}`);
  }
}
EOF
